package com.graduation.club.domain; import org.springframework.boot.CommandLineRunner;import org.springframework.core.annotation.Order;import org.springframework.context.annotation.*;
@org.springframework.context.annotation.Profile({"dev","test","ci"}) @Configuration public class ProjectDataSeed{@Bean @Order(10) CommandLineRunner seedProject(ClubRepository clubs){return args->{if(clubs.count()==0){var c=new Club();c.setName("光影摄影社");c.setCategory("文化艺术");c.setDescription("校园摄影、后期与影像分享活动");c.setPresident("林同学");c.setContact("club@example.edu");c.setMemberLimit(120);c.setStatus("ACTIVE"); clubs.save(c);}};}}
